private static long[] readVar(byte[] b, int p) {
    if (p >= b.length) return null;
    int first = b[p] & 0xff;
    int w = 1 << (first >>> 6);
    if (p + w > b.length) return null;
    long v = first & 0x3f;
    for (int i=1;i<w;i++) v = (v<<8) | (b[p+i]&0xff);
