package offline;

import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * Union of disjoint, non adjacent half-open intervals of packet numbers or sequence numbers.
 * Intervals are merged on insertion, so the ledger itself is the canonical merged view.
 */
public final class RangeSet {

    private final TreeMap<Long, Long> map = new TreeMap<>();

    /** Adds [start,end); empty ranges are ignored. */
    public void add(long start, long end) {
        if (end <= start) {
            return;
        }
        Map.Entry<Long, Long> floor = map.floorEntry(start);
        if (floor != null && floor.getValue() >= start) {
            start = floor.getKey();
            end = Math.max(end, floor.getValue());
            map.remove(floor.getKey());
        }
        while (true) {
            Map.Entry<Long, Long> next = map.ceilingEntry(start);
            if (next == null || next.getKey() > end) {
                break;
            }
            end = Math.max(end, next.getValue());
            map.remove(next.getKey());
        }
        map.put(start, end);
    }

    public boolean isEmpty() {
        return map.isEmpty();
    }

    /** Number of merged disjoint intervals. */
    public int intervals() {
        return map.size();
    }

    /** Total cardinality of the union; may reach 2^62. */
    public long count() {
        long total = 0;
        for (Map.Entry<Long, Long> e : map.entrySet()) {
            total += e.getValue() - e.getKey();
        }
        return total;
    }

    /** Cardinality of the union from 0 up to the first gap. */
    public long prefix() {
        Long end = map.get(0L);
        return end == null ? 0L : end;
    }

    /** Sorted [start,end] pairs for the JSON output. */
    public List<Object> rows() {
        List<Object> out = new ArrayList<>();
        for (Map.Entry<Long, Long> e : map.entrySet()) {
            List<Object> pair = new ArrayList<>(2);
            pair.add(e.getKey());
            pair.add(e.getValue());
            out.add(pair);
        }
        return out;
    }

    /** Feeds unsigned big-endian 8-byte start then end of every interval into the digest. */
    public void digest(MessageDigest md) {
        byte[] buf = new byte[8];
        for (Map.Entry<Long, Long> e : map.entrySet()) {
            put64(buf, e.getKey());
            md.update(buf);
            put64(buf, e.getValue());
            md.update(buf);
        }
    }

    static void put64(byte[] buf, long value) {
        for (int i = 0; i < 8; i++) {
            buf[i] = (byte) (value >>> (56 - 8 * i));
        }
    }
}
