package offline;

import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * Sparse byte ledger for stream and CRYPTO reassembly. Stored segments are disjoint; equal
 * overlapping writes are accepted, differing overlaps are reported to the caller. Every mutation
 * is journalled so the enclosing packet transaction can roll the ledger back.
 */
public final class ByteStore {

    /** Immutable stored segment; data.length == end - start. */
    private static final class Seg {
        final long start;
        final long end;
        final byte[] data;

        Seg(long start, long end, byte[] data) {
            this.start = start;
            this.end = end;
            this.data = data;
        }
    }

    private final TreeMap<Long, Seg> segs = new TreeMap<>();

    public boolean isEmpty() {
        return segs.isEmpty();
    }

    /**
     * Stores data at offset. Returns false when an overlapping byte differs from the stored one.
     * Nothing is modified in that case.
     */
    public boolean insert(long off, byte[] data, List<Undo> journal) {
        if (data.length == 0) {
            return true;
        }
        final long end = off + data.length;
        List<Seg> overlap = overlapping(off, end);
        for (Seg s : overlap) {
            long lo = Math.max(off, s.start);
            long hi = Math.min(end, s.end);
            for (long i = lo; i < hi; i++) {
                if (data[(int) (i - off)] != s.data[(int) (i - s.start)]) {
                    return false;
                }
            }
        }
        final List<Seg> removed = new ArrayList<>(overlap.size());
        final List<Seg> added = new ArrayList<>(overlap.size() + 1);
        for (Seg s : overlap) {
            segs.remove(s.start);
            removed.add(s);
            if (s.start < off) {
                added.add(new Seg(s.start, off, Arrays.copyOfRange(s.data, 0, (int) (off - s.start))));
            }
            if (s.end > end) {
                int from = (int) (end - s.start);
                added.add(new Seg(end, s.end, Arrays.copyOfRange(s.data, from, s.data.length)));
            }
        }
        added.add(new Seg(off, end, data));
        for (Seg s : added) {
            segs.put(s.start, s);
        }
        journal.add(new Undo() {
            @Override
            public void undo() {
                for (Seg s : added) {
                    segs.remove(s.start);
                }
                for (Seg s : removed) {
                    segs.put(s.start, s);
                }
            }
        });
        return true;
    }

    private List<Seg> overlapping(long off, long end) {
        List<Seg> out = new ArrayList<>();
        Long first = segs.floorKey(off);
        if (first == null) {
            first = segs.ceilingKey(off);
        }
        if (first == null) {
            return out;
        }
        for (Map.Entry<Long, Seg> e = segs.ceilingEntry(first); e != null; e = segs.higherEntry(e.getKey())) {
            Seg s = e.getValue();
            if (s.start >= end) {
                break;
            }
            if (s.end <= off) {
                continue;
            }
            out.add(s);
        }
        return out;
    }

    /** Sorted half-open unions of the stored bytes with adjacent segments merged. */
    public List<Object> ranges() {
        List<Object> out = new ArrayList<>();
        long start = -1;
        long end = -1;
        for (Seg s : segs.values()) {
            if (start < 0) {
                start = s.start;
                end = s.end;
            } else if (s.start <= end) {
                end = Math.max(end, s.end);
            } else {
                out.add(pair(start, end));
                start = s.start;
                end = s.end;
            }
        }
        if (start >= 0) {
            out.add(pair(start, end));
        }
        return out;
    }

    private static List<Object> pair(long start, long end) {
        List<Object> p = new ArrayList<>(2);
        p.add(start);
        p.add(end);
        return p;
    }

    /** Number of stored bytes. */
    public long unique() {
        long total = 0;
        for (Seg s : segs.values()) {
            total += s.end - s.start;
        }
        return total;
    }

    /** Length of the contiguous run of stored bytes starting at offset 0. */
    public long prefix() {
        long at = 0;
        while (true) {
            Seg s = segs.get(at);
            if (s == null) {
                return at;
            }
            at = s.end;
        }
    }

    /** Feeds exactly the contiguous prefix bytes into the digest. */
    public void digestPrefix(MessageDigest md) {
        long at = 0;
        while (true) {
            Seg s = segs.get(at);
            if (s == null) {
                return;
            }
            md.update(s.data);
            at = s.end;
        }
    }
}
